#!/bin/sh
# Name: FinanceWiki 업데이트
# Author: kindle-lab
# Icon: data:image/png;base64,
# DontUseFBInk
# Tap once from the library: installs a newer FinanceWiki Kindle via KPM, or
# reports that this one is current. Messages use the reader's own screen.
KPM=/var/local/kmc/bin/kpm
PKG=/mnt/us/kmc/kpm/packages/fw
FEED=https://raw.githubusercontent.com/kindle-lab/financewiki-kindle/main/manifest.json
LOG=/mnt/us/kmc/kpm/fw-update.log
LOCK=/tmp/fw-update.lock
mkdir "$LOCK" 2>/dev/null || exit 0
trap 'rmdir "$LOCK" 2>/dev/null' EXIT
exec >>"$LOG" 2>&1
echo "=== $(date '+%Y-%m-%dT%H:%M:%S') FinanceWiki update"
show() { (cd "$PKG" 2>/dev/null && printf '@message %s\n' "$1" | ./bin/financewiki --progress >/dev/null 2>&1); }
home() { sleep "${1:-3}"; lipc-set-prop com.lab126.appmgrd start app://com.lab126.booklet.home >/dev/null 2>&1; }
# Highest "version": [a, b, c] in a manifest, as "a b c".
versions() { tr -d ' \t\r\n' | grep -o '"version":\[[0-9]*,[0-9]*,[0-9]*\]' | sed 's/.*\[\([0-9]*\),\([0-9]*\),\([0-9]*\)\]/\1 \2 \3/' | sort -n -k1,1 -k2,2 -k3,3 | tail -n 1; }
newer() { set -- $1 $2; [ "$1" -gt "$4" ] || { [ "$1" -eq "$4" ] && { [ "$2" -gt "$5" ] || { [ "$2" -eq "$5" ] && [ "$3" -gt "$6" ]; }; }; }; }
dotted() { echo "$1" | tr ' ' '.'; }
show "업데이트를 확인하는 중"
installed=$(versions < "$PKG/manifest.json" 2>/dev/null)
remote=$(curl -fsSL --connect-timeout 8 --max-time 30 "$FEED" 2>/dev/null | versions)
echo "installed=$installed remote=$remote"
if [ -z "$remote" ]; then show "업데이트를 확인하지 못했어요 · Wi-Fi를 확인하세요"; home 4; exit 0; fi
if [ -n "$installed" ] && ! newer "$remote" "$installed"; then show "최신 버전이에요 · $(dotted "$installed")"; home 3; exit 0; fi
show "새 버전 $(dotted "$remote") 설치 중"
if "$KPM" -y install fw; then
    show "설치 완료 · $(dotted "$remote")"; echo "installed $remote"
else
    show "설치하지 못했어요 · 잠시 뒤 다시 눌러 주세요"; echo "kpm install failed"
fi
home 3
exit 0
